def descifrar(datos, clave):
    if not clave:
        raise ValueError("La clave no puede estar vacía.")

    resultado = bytearray()
    clave_largo = len(clave)

    for i, byte in enumerate(datos):
        resultado.append(byte ^ clave[i % clave_largo])

    return bytes(resultado)
